const output = $json.output ?? $json.text ?? $json.response ?? '';

if (typeof output !== 'string' || !output.trim()) {
  throw new Error('AI Agent returned no final brief. Inspect the AI Agent execution and its tool calls.');
}

return [{
  json: {
    brief: output.trim()
  }
}];

