parameters.jsCode:
const brief = $('Extract: Brief').first().json.brief;
let b = null;
try {
  b = $('Wait: Eval Result').first().json.body;
} catch (e) {}
const output = b && b.ok === true && typeof b.output === 'string' ? b.output.trim() : '';
const content = output
  ? brief + '\n\n---\n\n## Eval result\n\n```\n' + output + '\n```'
  : brief;
return [{ json: { content } }];
